//! Plain color value types, mirroring the `ColorSpace` structs of the C++ header.
//!
//! Every component is an `f32` so that the arithmetic in [`crate::color::converter`]
//! reproduces the single-precision rounding of the original library exactly.

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct RGB {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl RGB {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        RGB { r, g, b }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HSL {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

