    pub fn new(h: f32, s: f32, l: f32) -> Self {
        HSL { h, s, l }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HSV {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

impl HSV {
    pub fn new(h: f32, s: f32, v: f32) -> Self {
        HSV { h, s, v }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct CMYK {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

impl CMYK {
    pub fn new(c: f32, m: f32, y: f32, k: f32) -> Self {
        CMYK { c, m, y, k }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct YUV {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl YUV {
    pub fn new(y: f32, u: f32, v: f32) -> Self {
        YUV { y, u, v }
    }
