//! Color space conversions and channel operations.
//!
//! All arithmetic is done in `f32` in the same operation order as the C++
//! library so that the rounding of every intermediate value matches.

use super::types::{CMYK, HSL, HSV, RGB, YUV};

fn max3(a: f32, b: f32, c: f32) -> f32 {
    let mut m = a;
    if b > m {
        m = b;
    }
    if c > m {
        m = c;
    }
    m
}

fn min3(a: f32, b: f32, c: f32) -> f32 {
    let mut m = a;
    if b < m {
        m = b;
    }
    if c < m {
        m = c;
    }
    m
}

fn clamp01(v: f32) -> f32 {
    if v < 0.0 {
        0.0
    } else if v > 1.0 {
        1.0
    } else {
        v
    }
}

/// Hue angle in degrees shared by the HSL and HSV conversions.
fn hue_degrees(r: f32, g: f32, b: f32, max: f32, delta: f32) -> f32 {
    let mut h = if max == r {
        60.0 * ((g - b) / delta % 6.0)
    } else if max == g {
        60.0 * ((b - r) / delta + 2.0)
    } else {
        60.0 * ((r - g) / delta + 4.0)
    };
    if h < 0.0 {
        h += 360.0;
    }
    h
}

/// The `hue2rgb` helper of the classic HSL -> RGB algorithm.
fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: &RGB) -> HSL {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = max3(r, g, b);
        let min = min3(r, g, b);
        let delta = max - min;

        let l = (max + min) / 2.0;
        let mut h = 0.0f32;
        let mut s = 0.0f32;
        if delta != 0.0 {
            s = delta / (1.0 - (2.0 * l - 1.0).abs());
            h = hue_degrees(r, g, b, max, delta);
        }
        HSL::new(h, s, l)
    }

    pub fn rgb_to_hsv(rgb: &RGB) -> HSV {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = max3(r, g, b);
        let min = min3(r, g, b);
        let delta = max - min;

        let v = max;
        let mut h = 0.0f32;
        let mut s = 0.0f32;
        if max != 0.0 {
            s = delta / max;
        }
        if delta != 0.0 {
            h = hue_degrees(r, g, b, max, delta);
        }
        HSV::new(h, s, v)
    }

    pub fn rgb_to_cmyk(rgb: &RGB) -> CMYK {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = max3(r, g, b);
        let k = 1.0 - max;

        if k == 1.0 {
            return CMYK::new(0.0, 0.0, 0.0, k);
        }
        let c = (1.0 - r - k) / (1.0 - k);
        let m = (1.0 - g - k) / (1.0 - k);
        let y = (1.0 - b - k) / (1.0 - k);
        CMYK::new(c, m, y, k)
    }

    pub fn rgb_to_yuv(rgb: &RGB) -> YUV {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let y = 0.299 * r + 0.587 * g + 0.114 * b;
        let u = -0.147 * r - 0.289 * g + 0.436 * b;
        let v = 0.615 * r - 0.515 * g - 0.100 * b;
        YUV::new(y, u, v)
    }

    pub fn hsl_to_rgb(hsl: &HSL) -> RGB {
        if hsl.s == 0.0 {
            return RGB::new(hsl.l, hsl.l, hsl.l);
        }
        let h = hsl.h / 360.0;
        let (s, l) = (hsl.s, hsl.l);
        let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
        let p = 2.0 * l - q;
        RGB::new(
            hue_to_rgb(p, q, h + 1.0 / 3.0),
            hue_to_rgb(p, q, h),
            hue_to_rgb(p, q, h - 1.0 / 3.0),
        )
    }

    pub fn adjust_brightness(rgb: &RGB, factor: f32) -> RGB {
        RGB::new(
            clamp01(rgb.r * factor),
            clamp01(rgb.g * factor),
            clamp01(rgb.b * factor),
        )
    }

    /// Scales saturation in HSL space, clamping the saturation to `[0, 1]`
    /// before converting back.
    pub fn adjust_saturation(rgb: &RGB, factor: f32) -> RGB {
        let mut hsl = ColorConverter::rgb_to_hsl(rgb);
        hsl.s = clamp01(hsl.s * factor);
        let out = ColorConverter::hsl_to_rgb(&hsl);
        RGB::new(clamp01(out.r), clamp01(out.g), clamp01(out.b))
    }

    pub fn grayscale(rgb: &RGB) -> RGB {
        let gray = 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
        RGB::new(gray, gray, gray)
    }

    pub fn invert(rgb: &RGB) -> RGB {
        RGB::new(1.0 - rgb.r, 1.0 - rgb.g, 1.0 - rgb.b)
    }

    pub fn color_distance(a: &RGB, b: &RGB) -> f32 {
        let dr = a.r - b.r;
        let dg = a.g - b.g;
        let db = a.b - b.b;
        (dr * dr + dg * dg + db * db).sqrt()
    }
}

