//! Reproduction of `std::ostream`'s default floating point formatting.
//!
//! `std::cout << some_float` promotes the value to `double` and prints it with
//! `defaultfloat` and precision 6, i.e. exactly `printf("%g")` with a precision
//! of 6 significant digits.

/// Drops the trailing zeros (and a bare trailing dot) the way `%g` does.
fn trim_fraction(s: &str) -> &str {
    if !s.contains('.') {
        return s;
    }
    let t = s.trim_end_matches('0');
    t.strip_suffix('.').unwrap_or(t)
}

/// Formats `value` the way `std::cout` would with default flags.
pub fn ostream_float(value: f32) -> String {
    let v = value as f64;

    if v.is_nan() {
        return if v.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        };
    }
    if v.is_infinite() {
        return if v < 0.0 {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }

    // Rounding to 6 significant digits first yields the decimal exponent that
    // `%g` uses to pick between the scientific and the fixed representation.
    let sci = format!("{:.5e}", v);
    let (mantissa, exponent) = sci.split_once('e').expect("LowerExp always emits 'e'");
    let exp: i32 = exponent.parse().expect("LowerExp always emits an integer");

    if exp < -4 || exp >= 6 {
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", trim_fraction(mantissa), sign, exp.abs())
    } else {
        // Total significant digits stay at 6: one before the point plus `exp`
        // digits already consumed by the integral part.
        let fixed = format!("{:.*}", (5 - exp) as usize, v);
        trim_fraction(&fixed).to_string()
    }
}

/// Equivalent of `std::stof`: converts the longest leading numeric prefix and
/// aborts the way an uncaught `std::invalid_argument` would when there is none.
pub fn stof(text: &str) -> f32 {
    match parse_float_prefix(text) {
        Some(v) => v,
        None => {
            eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
            eprintln!("  what():  stof");
            std::process::abort();
        }
    }
}

fn parse_float_prefix(text: &str) -> Option<f32> {
    let bytes = text.as_bytes();
    let mut i = 0;

    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let start = i;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        i += 1;
    }

    let lowered = text[i..].to_ascii_lowercase();
    if lowered.starts_with("inf") {
        let len = if lowered.starts_with("infinity") { 8 } else { 3 };
        return text[start..i + len].parse::<f32>().ok().or(Some(
            if bytes[start] == b'-' {
                f32::NEG_INFINITY
            } else {
                f32::INFINITY
            },
        ));
    }
    if lowered.starts_with("nan") {
        return Some(if bytes[start] == b'-' {
            -f32::NAN
        } else {
            f32::NAN
        });
    }

    let digits_start = i;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }
    if i == digits_start || (i == digits_start + 1 && bytes[digits_start] == b'.') {
        return None;
    }

    // An exponent only counts when it is complete.
    if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
        let mut j = i + 1;
        if j < bytes.len() && (bytes[j] == b'+' || bytes[j] == b'-') {
            j += 1;
        }
        let exp_digits = j;
        while j < bytes.len() && bytes[j].is_ascii_digit() {
            j += 1;
        }
        if j > exp_digits {
            i = j;
        }
    }

    text[start..i].parse::<f32>().ok()
}

