mod color;

use std::io::{self, BufWriter, Write};

use color::{ostream_float as f, stof, ColorConverter, RGB};

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let argc = argv.len();

    let mut colors: Vec<RGB> = Vec::new();

    // 添加一些默认颜色
    colors.push(RGB::new(0.1, 0.2, 0.3));
    colors.push(RGB::new(0.4, 0.5, 0.6));
    colors.push(RGB::new(0.7, 0.2, 0.1));
    colors.push(RGB::new(0.3, 0.8, 0.4));
    colors.push(RGB::new(0.9, 0.1, 0.8));

    // 从命令行参数添加更多颜色
    let mut i = 1;
    while i + 2 < argc {
        let r = stof(&argv[i]);
        let g = stof(&argv[i + 1]);
        let b = stof(&argv[i + 2]);
        colors.push(RGB::new(r, g, b));
        i += 3;
    }

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    // 执行多个转换和操作
    for i in 0..colors.len() {
        let rgb = colors[i];

        // 基本转换
        let hsl = ColorConverter::rgb_to_hsl(&rgb);
        let hsv = ColorConverter::rgb_to_hsv(&rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(&rgb);
        let yuv = ColorConverter::rgb_to_yuv(&rgb);

        // 亮度调整
        let bright = ColorConverter::adjust_brightness(&rgb, 1.2);
        let dark = ColorConverter::adjust_brightness(&rgb, 0.8);

        // 饱和度调整
        let saturated = ColorConverter::adjust_saturation(&rgb, 1.5);

        // 灰度化
        let gray = ColorConverter::grayscale(&rgb);

        // 反转
        let inverted = ColorConverter::invert(&rgb);

        // 输出结果
        write!(out, "Color {}: ", i).unwrap();
        write!(out, "{} {} {} ", f(rgb.r), f(rgb.g), f(rgb.b)).unwrap();
        write!(out, "{} {} {} ", f(hsl.h), f(hsl.s), f(hsl.l)).unwrap();
        write!(out, "{} {} {} ", f(hsv.h), f(hsv.s), f(hsv.v)).unwrap();
        write!(
            out,
            "{} {} {} {} ",
            f(cmyk.c),
            f(cmyk.m),
            f(cmyk.y),
            f(cmyk.k)
        )
        .unwrap();
        write!(out, "{} {} {} ", f(yuv.y), f(yuv.u), f(yuv.v)).unwrap();
        write!(out, "{} {} {} ", f(bright.r), f(bright.g), f(bright.b)).unwrap();
        write!(out, "{} {} {} ", f(dark.r), f(dark.g), f(dark.b)).unwrap();
        write!(
            out,
            "{} {} {} ",
            f(saturated.r),
            f(saturated.g),
            f(saturated.b)
        )
        .unwrap();
        write!(out, "{} {} {} ", f(gray.r), f(gray.g), f(gray.b)).unwrap();
        write!(
            out,
            "{} {} {} ",
            f(inverted.r),
            f(inverted.g),
            f(inverted.b)
        )
        .unwrap();

        // 如果是最后一个颜色，计算与第一个颜色的距离
        if i == colors.len() - 1 && colors.len() > 1 {
            let dist = ColorConverter::color_distance(&rgb, &colors[0]);
            write!(out, "{} ", f(dist)).unwrap();
        }

        writeln!(out).unwrap();
        out.flush().unwrap();
    }
}

