use super::types::{CMYK, HSL, HSV, RGB, YUV};

fn max3(a: f32, b: f32, c: f32) -> f32 {
    let mut m = a;
    if b > m {
        m = b;
    }
    if c > m {
        m = c;
    }
    m
}

fn min3(a: f32, b: f32, c: f32) -> f32 {
    let mut m = a;
    if b < m {
        m = b;
    }
    if c < m {
        m = c;
    }
    m
}

fn clamp01(v: f32) -> f32 {
    if v < 0.0 {
        0.0
    } else if v > 1.0 {
        1.0
    } else {
        v
    }
}

/// Hue angle in degrees shared by the HSL and HSV conversions.
fn hue_degrees(r: f32, g: f32, b: f32, max: f32, delta: f32) -> f32 {
    let mut h = if max == r {
        60.0 * ((g - b) / delta % 6.0)
    } else if max == g {
        60.0 * ((b - r) / delta + 2.0)
    } else {
        60.0 * ((r - g) / delta + 4.0)
    };
    if h < 0.0 {
        h += 360.0;
    }
    h
}

/// The `hue2rgb` helper of the classic HSL -> RGB algorithm.
fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: &RGB) -> HSL {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = max3(r, g, b);
        let min = min3(r, g, b);
        let delta = max - min;

