fn parse_target(s:&str)->(f64,f64){
    // C++ printed 6 significant digits; recover the rounding interval
    let v: f64 = s.parse().unwrap();
    let digits = s.chars().filter(|c| c.is_ascii_digit()).count();
    let _ = digits;
    // find decimal exponent
    let e = if v==0.0 {0} else { v.abs().log10().floor() as i32 };
    let half = 0.5f64 * 10f64.powi(e-5);
    (v-half, v+half)
}
fn main(){
