/// Hue angle in degrees shared by the HSL and HSV conversions.
///
/// The hue is first built as a value in `[0, 6)` and only then scaled by 60,
/// which is what keeps the rounding identical to the C++ library.
fn hue_degrees(r: f32, g: f32, b: f32, max: f32, delta: f32) -> f32 {
    let h = if max == r {
        (g - b) / delta + if g < b { 6.0 } else { 0.0 }
    } else if max == g {
        (b - r) / delta + 2.0
    } else {
        (r - g) / delta + 4.0
    };
    h * 60.0
}

