  my $o2=`$RS  $q 2>/tmp/e2`; my $r2=$?; my $e2=`cat /tmp/e2`;
  my $bad=0;
  $bad=1 if $o1 ne $o2;
  $bad=2 if ($r1==0) != ($r2==0);
  $bad=3 if $e1 ne $e2;
  if ($bad) { $fails++;
    print "DIFF($bad) [@$c] rc=$r1/$r2\n";
    if ($bad==1) { my @l1=split /\n/,$o1; my @l2=split /\n/,$o2;
