/// Hue angle in degrees shared by the HSL and HSV conversions.
///
/// The hue is first built as a value in `[0, 6)`, normalised to `[0, 1)` and
/// only then scaled to degrees. Keeping that exact sequence of roundings is
/// what makes the round trip through [`ColorConverter::hsl_to_rgb`] agree with
/// the C++ library bit for bit.
fn hue_degrees(r: f32, g: f32, b: f32, max: f32, delta: f32) -> f32 {
    let h = if max == r {
        (g - b) / delta + if g < b { 6.0 } else { 0.0 }
    } else if max == g {
        (b - r) / delta + 2.0
    } else {
        (r - g) / delta + 4.0
    };
    h / 6.0 * 360.0
}

/// The `hue2rgb` helper of the classic HSL -> RGB algorithm.
fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

